'use strict';
const fs=require('node:fs');const path=require('node:path');const {buildCore}=require('./performance-core-build.cjs');
function browserEntry(phase){return `
import React,{useState} from 'react';import {createRoot} from 'react-dom/client';
${phase==='after'?"import {ImageRecoveryProvider as RecoveryProvider,ImageRecoveryControls as RecoveryControls} from './components/reliable-image';":"const RecoveryProvider=React.Fragment;const RecoveryControls=()=>null;"}
const query=new URLSearchParams(location.search),count=[12,120,600].includes(Number(query.get('count')))?Number(query.get('count')):12;
const errorMode=query.get('mode')==='fail-once'?'fail-once':'success';
window.fixtureMetrics={lcp:null,cls:null,errors:[],firstVisibleMs:null,firstImageLoadCallbackMs:null,firstImageLoadCallbackDefinition:'DOM image load/complete callback timestamp; not visibility or paint',phase:${JSON.stringify(phase)},count};
try{new PerformanceObserver(list=>{const entries=list.getEntries();if(entries.length)window.fixtureMetrics.lcp=entries.at(-1).startTime;}).observe({type:'largest-contentful-paint',buffered:true});}catch{}
try{new PerformanceObserver(list=>{for(const entry of list.getEntries())if(!entry.hadRecentInput)window.fixtureMetrics.cls+=entry.value;}).observe({type:'layout-shift',buffered:true});window.fixtureMetrics.cls=0;}catch{}
addEventListener('error',event=>{if(event.error)window.fixtureMetrics.errors.push(String(event.message));});
function App(){const [identity,setIdentity]=useState(0),[source,setSource]=useState(0),[lightbox,setLightbox]=useState(false);return <RecoveryProvider><header><h1>Identical image recovery fixture</h1><p>${phase}: {count} synthetic images; same SVG bytes/dimensions/delay; repeated sources every four identities.</p><button id="identity-swap" onClick={()=>setIdentity(value=>value?0:1)}>same src / change identity</button><button id="source-swap" onClick={()=>setSource(value=>value?0:1)}>A → B → A source</button><button id="open-lightbox" onClick={()=>setLightbox(true)}>open synthetic image</button></header><main>{Array.from({length:count},(_,index)=>{const module=implementations[index%implementations.length];return <figure key={index} data-identity={index+':'+identity}><module.Picture src={'/synthetic-image.svg?asset='+Math.floor(index/4)+'&source='+source+'&mode='+errorMode+'&run='+encodeURIComponent(query.get('run')??'stable')} identityKey={'identity:'+index+':'+identity} alt={'合成身份 '+index+' / '+module.name} priority={index===0} complete fit="contain"/></figure>;})}</main><RecoveryControls/>{lightbox&&<PhotoLightbox src="/synthetic-image.svg?asset=original&mode=success" label="合成原图身份" onClose={()=>setLightbox(false)}/>}</RecoveryProvider>;}
const observer=new MutationObserver(()=>{const first=document.querySelector('main img');if(first&&!first.dataset.observed){first.dataset.observed='true';const done=()=>{if(first.naturalWidth>0&&window.fixtureMetrics.firstImageLoadCallbackMs===null)window.fixtureMetrics.firstImageLoadCallbackMs=performance.now();};first.addEventListener('load',done,{once:true});if(first.complete)done();}});observer.observe(document.body,{childList:true,subtree:true});createRoot(document.getElementById('root')).render(<App/>);
window.readFixtureMetrics=()=>({...window.fixtureMetrics,domCount:document.querySelectorAll('*').length,imgCount:document.querySelectorAll('main img').length,altCount:[...document.querySelectorAll('main img')].filter(image=>image.alt).length,resources:performance.getEntriesByType('resource').filter(row=>row.initiatorType==='img').map(row=>({name:row.name,startTime:row.startTime,responseEnd:row.responseEnd,transferSize:row.transferSize,encodedBodySize:row.encodedBodySize})),imageState:[...document.querySelectorAll('main img')].map(image=>({src:image.getAttribute('src'),complete:image.complete,width:image.naturalWidth,loading:image.loading,fetchPriority:image.fetchPriority,decoding:image.decoding}))});
`;
}
async function build(output){if(!path.isAbsolute(output))throw new Error('Absolute output directory required.');fs.mkdirSync(output,{recursive:true});for(const phase of ['before','after']){await buildCore({phase,platform:'browser',output:path.join(output,phase+'.js'),extraEntry:browserEntry(phase)});fs.writeFileSync(path.join(output,phase+'.html'),`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Image ${phase} fixture</title><link rel="stylesheet" href="/fixture.css"><div id="root"></div><script src="/${phase}.js"></script></html>`);}const css=`*{box-sizing:border-box}body{margin:0;padding:12px;font:14px/1.5 system-ui}header{max-width:100%;overflow-wrap:anywhere}button{min-height:44px;margin:4px;max-width:100%;white-space:normal}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,200px),1fr));gap:16px}figure{width:100%;height:150px;min-width:0;margin:0;overflow:hidden}figure>img{display:block;width:100%;height:100%;object-fit:contain}figure>.ri-fallback{width:100%;height:150px} .photo-lightbox{position:fixed;inset:0;z-index:999;background:#111e;color:white;display:grid;place-content:center}.photo-lightbox figure{height:min(75vh,600px);width:min(90vw,800px)}.photo-lightbox img{width:100%;height:100%;object-fit:contain}\n`;let imageCss='';const file=path.resolve(__dirname,'../../../components/reliable-image.css');if(fs.existsSync(file))imageCss=fs.readFileSync(file,'utf8');fs.writeFileSync(path.join(output,'fixture.css'),css+imageCss);}
if(require.main===module)build(process.argv[2]).then(()=>console.log('Built before/after browser fixture only; browser metrics are not measured by this command.')).catch(error=>{console.error(error);process.exitCode=1;});
module.exports={build};
